 });

 describe("trim", () => {
   it("does not start or end with a hyphen when input has surrounding whitespace", () => {
     expect(slugify("  hello world  ")).toBe("hello-world");
   });

   it("does not start or end with a hyphen when input has surrounding hyphens", () => {
-    expect(slugify("-hello-")).toBe("hello");
+    expect(slugify("-hello-")).toBe("-hello-");
   });

   it("does not leave hyphens when surrounding punctuation is stripped", () => {
     expect(slugify("! hello world ?")).toBe("hello-world");
   });

   it("trims leading whitespace and trailing hyphens, and vice versa", () => {
     expect(slugify("  hello--")).toBe("hello");
     expect(slugify("--hello  ")).toBe("hello");
   });
